CREATE TABLE memory_settings(owner_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE TABLE memory_records(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, project_id TEXT, scope TEXT NOT NULL CHECK(scope IN ('profile','project','artifact','frame')), frame_id TEXT, agent_key TEXT, status TEXT NOT NULL CHECK(status IN ('active','pending_review','needs_review','rejected','superseded','archived')), revision INTEGER NOT NULL CHECK(revision>0), content_hash TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE INDEX memory_acl ON memory_records(owner_id,project_id,scope,status);
CREATE INDEX memory_frame ON memory_records(project_id,frame_id);
CREATE TABLE memory_sources(record_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE TABLE memory_revisions(record_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(record_id,revision)) STRICT;
CREATE TABLE memory_review_events(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, mode TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE memory_change_proposals(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, project_id TEXT, expected_revision INTEGER NOT NULL, expected_hash TEXT NOT NULL, candidate_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','stale_proposal')), data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE TABLE memory_categories(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, auto_recall INTEGER NOT NULL CHECK(auto_recall IN (0,1))) STRICT;
CREATE TABLE memory_operations(owner_id TEXT NOT NULL, operation_key TEXT NOT NULL, request_hash TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(owner_id,operation_key)) STRICT;
CREATE VIRTUAL TABLE memory_fts USING fts5(record_id UNINDEXED, terms, tokenize='unicode61');
CREATE TABLE memory_extraction_cursors(owner_id TEXT NOT NULL, project_id TEXT NOT NULL, session_id TEXT NOT NULL, watermark INTEGER NOT NULL, PRIMARY KEY(owner_id,project_id,session_id)) STRICT;
CREATE TABLE memory_dream_schedules(owner_id TEXT NOT NULL, project_id TEXT NOT NULL, cwd TEXT NOT NULL, last_interaction INTEGER NOT NULL, PRIMARY KEY(owner_id,project_id)) STRICT;
CREATE TABLE memory_dream_runs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, project_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('dream','extraction')), logical_key TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','interrupted')), lease_until INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(owner_id,logical_key)) STRICT;
CREATE INDEX memory_run_status ON memory_dream_runs(owner_id,status);
CREATE TABLE memory_dream_proposals(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES memory_dream_runs(id) ON DELETE CASCADE, record_id TEXT REFERENCES memory_records(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(run_id,record_id)) STRICT;
CREATE TABLE memory_recall_events(owner_id TEXT NOT NULL, project_id TEXT NOT NULL, turn_id TEXT NOT NULL, record_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(owner_id,project_id,turn_id,record_id)) STRICT;
CREATE TABLE memory_project_settings(owner_id TEXT NOT NULL, project_id TEXT NOT NULL, auto_recall INTEGER NOT NULL CHECK(auto_recall IN (0,1)), PRIMARY KEY(owner_id,project_id)) STRICT;
CREATE TABLE memory_background_events(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, project_id TEXT NOT NULL, created_at INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
